INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19901, 'Ezekiel 23:9', 'Ezekiel', 23, 9, '&nbsp;نو په دې وجه ما هغه خپلو عاشقانو ته حواله کړه، اسوريانو ته چا سره چې د هغې شوق دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19902, 'Ezekiel 23:10', 'Ezekiel', 23, 10, '&nbsp;هغوئ هغه بربنډه کړه، د هغې نه يې زامن او لوڼه واخستل او هغه يې په تُوره ووژله. او هغه د نورو ښځو په مينځ کښې د عبرت مثال شوه، او سزا په هغې نازله شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19903, 'Ezekiel 23:11', 'Ezekiel', 23, 11, '&nbsp;د هغې خور اوحوليبه دا وليدل خو اوس هغه په شهوت پرستۍ او کنجرتوب کښې د خپلې خور نه ډېره زياته تېزه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19904, 'Ezekiel 23:12', 'Ezekiel', 23, 12, '&nbsp;اسورى مشرانو او آفسرانو او د ښائسته جامو جنګيالو ته او په آسونو سوارو آفسرانو ته، زياته په شوق کښې وه چې ښکلى ځوانان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19905, 'Ezekiel 23:13', 'Ezekiel', 23, 13, '&nbsp;نو ما وليدل چې هغې هم خپل ځان پليت کړو، او هغوئ دواړه په يوه لاره باندې لاړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19906, 'Ezekiel 23:14', 'Ezekiel', 23, 14, '&nbsp;خو هغې خپل کنجرتوب مخکښې جارى وساتلو. هغې د سړو تصويرونه په دېوال وليدل، د بابليانو تصويرونه چې په سور رنګ نقش شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19907, 'Ezekiel 23:15', 'Ezekiel', 23, 15, '&nbsp;هغوئ ملابندونه تړلى وُو او په سرونو يې غټ پټکى تړلى وُو، هغوئ ټولو د بابليانو د جنګى ګاډو د آفسرانو په شان لباس اغوستے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19908, 'Ezekiel 23:16', 'Ezekiel', 23, 16, '&nbsp;څنګه چې هغې هغوئ وليدل، نو هغوئ ته يې ډېر شوق وشو او ورپسې يې بابل ته قاصدان ورولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19909, 'Ezekiel 23:17', 'Ezekiel', 23, 17, '&nbsp;بيا بابليان راغلل د هغې سره بستره کښې يو ځائ شول، او په خپل شهوت سره يې هغه پليته کړه. وروستو د دې نه چې هغه د دوئ په وجه پليته شوه، هغه د هغوئ نه بېزاره شوه او د هغوئ نه واوړېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19910, 'Ezekiel 23:18', 'Ezekiel', 23, 18, '&nbsp;کله چې هغې په ښکاره توګه خپل کنجرتوب شروع کړو او خپل ځان يې ټولو ته لغړ کړو، زۀ د هغې نه بېزاره شوم او خپل مخ مې ترې نه واړولو لکه څنګه چې ما د هغې د خور نه اړولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19911, 'Ezekiel 23:19', 'Ezekiel', 23, 19, '&nbsp;خو هغه د پخوا نه هم ډېره زياته کنجره شوه لکه څنګه چې هغه په مِصر کښې د خپلې ځوانۍ په عمر کښې کنجره وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19912, 'Ezekiel 23:20', 'Ezekiel', 23, 20, '&nbsp;هغې هلته د خپلو عاشقانو سره شهوت بازى وکړه، د چا شرمګاه چې د خرونو په شان غټ وو او د چا انزال چې د آسونو په شان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19913, 'Ezekiel 23:21', 'Ezekiel', 23, 21, '&nbsp;نو تۀ د خپلې ځوانۍ د هغه مستۍ بيا خواهشمنده يې، لکه څنګه چې ستا په پېغلتوب کښې پردو سړو په مِصر کښې ستا د سينو سره لوبې وکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19914, 'Ezekiel 23:22', 'Ezekiel', 23, 22, '&nbsp;نو په دې وجه، اے اوحوليبه، مالِک قادر مطلق خُدائ داسې فرمائى، ”زۀ به ستا عاشقان ستا خلاف راپاڅوم، د چا نه چې تۀ اوړېدلې يې او نفرت ترې کوې، او زۀ به هغوئ ستا خلاف د هرې خوا نه راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19915, 'Ezekiel 23:23', 'Ezekiel', 23, 23, '&nbsp;بابليان او ټول د فقود او د شوع او د کوع خلق او هغوئ سره به ټول اسوريان، ښکلې ځوانان سړى، ټول آفسران او حاکمان، د جنګى ګاډو آفسران او د اوچت مقام خلق ټول په آسونو سوارۀ ستا خلاف راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19916, 'Ezekiel 23:24', 'Ezekiel', 23, 24, '&nbsp;هغوئ به ستا خلاف د وسلو، جنګى ګاډو او ريړو او د ډېرو خلقو او لوئ لښکر سره راشى. هغوئ به ستا خلاف هرې خوا ته مورچه شى او د لويو او وړو ډالونو او جنګى ټوپۍ په سر به په تا حمله وکړى. او زۀ به تا هغوئ ته د سزا دپاره حواله کړم. او هغوئ به د خپل قانون په مطابق تاسو له سزا درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19917, 'Ezekiel 23:25', 'Ezekiel', 23, 25, '&nbsp;زۀ به ستاسو خلاف خپله غصه نازله کړم، او هغوئ به تاسو سره د غصې سلوک وکړى. هغوئ به ستاسو پوزې او غوږونه پرې کړى، او په تاسو کښې چې څوک پاتې شى په تُوره به مړۀ کړے شى. هغوئ به ستاسو زامن او لوڼه بوځى، او تاسو نه چې څوک پاتې شى هغوئ به په اور کښې وسوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19918, 'Ezekiel 23:26', 'Ezekiel', 23, 26, '&nbsp;هغوئ به ستاسو نه جامې وباسى او قيمتى کالى به درنه واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19919, 'Ezekiel 23:27', 'Ezekiel', 23, 27, '&nbsp;نو زۀ به ستا هغه فحاشى او کنجرتوب ختم کړم کوم چې تا په مصر کښې شروع کړے وو. تۀ به نور دې څيزونو ته د خواهش نظر نۀ کوې او نۀ به مِصر يادوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19920, 'Ezekiel 23:28', 'Ezekiel', 23, 28, '&nbsp;نو ځکه مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ تاسو هغه خلقو ته حواله کوم چې تاسو ترې نفرت کوئ، هغوئ ته چا نه چې تاسو په بېزارۍ سره مخ اړولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19921, 'Ezekiel 23:29', 'Ezekiel', 23, 29, '&nbsp;هغوئ به تاسو سره د نفرت سلوک وکړى او هر هغه څيز به درنه يوسى کوم دپاره چې تاسو محنت کړے دے. تاسو به بربنډ او لغړ پرېږدى، او ستا د زناکارۍ شرم به څرګند شى. ستا فحاشۍ او زناکارۍ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19922, 'Ezekiel 23:30', 'Ezekiel', 23, 30, '&nbsp;دا هر څۀ په تا باندې راوستل، ځکه چې تۀ نورو قومونو پسې بې‌قراره وې او خپل ځان دې د هغوئ په بُتانو پليت کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19923, 'Ezekiel 23:31', 'Ezekiel', 23, 31, '&nbsp;تۀ د خپلې خور په لار لاړې، نو زۀ به د هغې پياله ستا په لاس کښې کېږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19924, 'Ezekiel 23:32', 'Ezekiel', 23, 32, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، تۀ به د خپلې خور پيالۍ وڅښې، يوه لويه او ژوره پيالۍ، دا به تا د خلقو د ټوقو او مسخرو کړى، ځکه چې دا پياله ډکه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19925, 'Ezekiel 23:33', 'Ezekiel', 23, 33, '&nbsp;تۀ به په خفګان او نشه اخته شې، د تباهۍ او د دهشت پيالۍ، يعنې ستا د خور سامريې پيالۍ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19926, 'Ezekiel 23:34', 'Ezekiel', 23, 34, '&nbsp;تۀ به دا وڅښې او تشه به يې کړې، او په ماتو شوو ټوکړو به يې شخوند ووهې او خپله سينه به د غم نه ووهې. ما مالِک قادر مطلق خُدائ دا وفرمائيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19927, 'Ezekiel 23:35', 'Ezekiel', 23, 35, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، د کله نه چې تا زۀ هېر کړے يم او وروستو خپل شا ته دې غورزولے يم، په دې وجه تۀ به خامخا د خپلې شهوت پرستۍ او زناکارۍ سزا وزغمې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19928, 'Ezekiel 23:36', 'Ezekiel', 23, 36, '&nbsp;مالِک خُدائ ما ته وفرمائيل، ”اے بنى آدمه، ولې تۀ به د اوحوله او اوحوليبه عدالت وکړې؟ نو هغوئ تۀ د هغوئ حرام کارونه مخامخ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19929, 'Ezekiel 23:37', 'Ezekiel', 23, 37, '&nbsp;ځکه چې هغوئ زنا وکړه او د هغوئ لاسونه په وينو سرۀ دى. هغوئ خپلو بُتانو سره زنا وکړه، تر دې چې هغوئ خپل زامن هم بُتانو ته د خوراک دپاره قربانى کړل، کوم چې هغوئ زما دپاره پېدا کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19930, 'Ezekiel 23:38', 'Ezekiel', 23, 38, '&nbsp;هغوئ ما سره هم دا وکړل چې، په هم هغه وخت کښې هغوئ زما مقدس کور پليت کړو او زما د سبت بې‌حرمتى يې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19931, 'Ezekiel 23:39', 'Ezekiel', 23, 39, '&nbsp;په هغه ورځ چې هغوئ خپل ماشومان خپلو بُتانو ته قربانى کړل، نو په هغه ورځ هغوئ زما مقدس کور ته ننوتل او د دې بې‌حرمتى يې وکړه. دا هغه څۀ دى چې هغوئ زما کور کښې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19932, 'Ezekiel 23:40', 'Ezekiel', 23, 40, '&nbsp;تر دې چې هغوئ د سړو دپاره قاصدان لېږلى وُو څوک چې د لرې ځائ نه راغلل، او کله چې هغوئ راورسېدل تا خپل ځان د هغوئ دپاره پاک کړو او خپلې سترګې دې تورې کړې او لا دا چې ځان دې په سرو زرو سنګار کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19933, 'Ezekiel 23:41', 'Ezekiel', 23, 41, '&nbsp;بيا تۀ په شانداره صوفې کښېناستلې چې مېز يې په مخکښې پروت وو په کوم چې تا هغه خوشبو او تېل اېښى وُو چې زما وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19934, 'Ezekiel 23:42', 'Ezekiel', 23, 42, '&nbsp;د ګڼو خلقو شور د هغې سره نزدې وو، تر دې چې مست او عياش خلق يې د صحرا نه راوستل او هغوئ دغه دواړو خوېندو ته په مټو کښې بنګړى واچول او ښکلى تاجونه يې ورته په سر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19935, 'Ezekiel 23:43', 'Ezekiel', 23, 43, '&nbsp;نو ما بيا د هغه چا په حقله ووئيل څوک چې د زناکارۍ په وجه ستړې شوې وه، اوس پرېږده چې هغوئ دا لکه د يو کنجرۍ په شان استعمال کړى، ځکه چې هغه هم داسې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19936, 'Ezekiel 23:44', 'Ezekiel', 23, 44, '&nbsp;او هغوئ د هغې سره زنا وکړه. لکه څنګه چې سړے د زناکارې سره څملى، نو هغوئ د هغه بې‌حيا ښځو اوحوله او اوحوليبه سره څملاستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19937, 'Ezekiel 23:45', 'Ezekiel', 23, 45, '&nbsp;خو صادقان به هغوئ ته د هغو ښځو سزا ورکړى څوک چې زنا او قتل کوى، ځکه چې هغوئ زناکارې دى او لاسونه يې په وينو سرۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19938, 'Ezekiel 23:46', 'Ezekiel', 23, 46, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، ”د هغوئ خلاف لوئ لښکر راوله او هغوئ يرې او لوټ مار ته حواله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19939, 'Ezekiel 23:47', 'Ezekiel', 23, 47, '&nbsp;د هغوئ دشمنان به هغوئ سنګسار کړى او په تُوره به يې ووژنى، هغوئ به د دوئ زامن او لوڼه مړۀ کړى او د هغوئ کورونه به وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19940, 'Ezekiel 23:48', 'Ezekiel', 23, 48, '&nbsp;نو زۀ به په دې مُلک کښې شهوت پرستى ختمه کړم، او ټولو ښځو ته به تنبيه مِلاو شى او هغوئ به نور ستا په نقش قدم نۀ ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19941, 'Ezekiel 23:49', 'Ezekiel', 23, 49, '&nbsp;تاسو به د خپلې شهوت پرستۍ دپاره سزا وزغمئ او د خپلې بُت پرستۍ د ګناهونو سزا به برداشت کړئ. نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک قادر مطلق خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19942, 'Ezekiel 24:1', 'Ezekiel', 24, 1, '&nbsp;د جلاوطنۍ په نهم کال، د لسمې مياشتې په لسمه ورځ، د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19943, 'Ezekiel 24:2', 'Ezekiel', 24, 2, '&nbsp;”اے بنى آدمه، د نن ورځې تاريخ وليکه، ځکه چې هم دا نن په دې تاريخ به د بابل بادشاه يروشلم محاصره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19944, 'Ezekiel 24:3', 'Ezekiel', 24, 3, '&nbsp;يو مثال دې سرکشه قوم ته ووايه او هغوئ ته ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى چې، د پخلى دېګ په اور کېږدئ او اوبۀ په کښې واچوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19945, 'Ezekiel 24:4', 'Ezekiel', 24, 4, '&nbsp;او په هغې کښې د غوښې بوټۍ واچوئ، ټولې ښې بوټۍ لکه ‎پتون او اوږى غوښه په کښې واچوئ. او د هم داسې ښو هډوکو نه يې ډک کړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19946, 'Ezekiel 24:5', 'Ezekiel', 24, 5, '&nbsp;د رمې نه د خاص څاروے غوښه په کښې واچوئ، او د دېګ لاندې خشاک کېږدئ. او اوبۀ وويشوئ، او هډوکى هم د غوښې سره پاخۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19947, 'Ezekiel 24:6', 'Ezekiel', 24, 6, '&nbsp;نو مالِک قادر مطلق خُدائ داسې فرمائى چې، افسوس دې وى د قاتلانو په ښار، لکه د هغه دېګ په شان چې زنګ وهلے وى د چا ګندګى چې نۀ اخوا کيږى، دېګ په يو شان سره خالى کړئ او خوښه نا خوښه مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19948, 'Ezekiel 24:7', 'Ezekiel', 24, 7, '&nbsp;کومه وينه چې يروشلم تويه کړه نو هغه په ميدان کښې په يو کولاو ګټ تويه شوه، داسې نۀ وو شوے چې ګنې په زمکه تويه شوه او دوړې پټه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19949, 'Ezekiel 24:8', 'Ezekiel', 24, 8, '&nbsp;نو په دې وجه به زۀ خپله غصه راوپاروم او د هغوئ نه به بدله واخلم او د هغۀ وينه به په کولاو کاڼى تويه کړم چې دا هم ښکاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19950, 'Ezekiel 24:9', 'Ezekiel', 24, 9, '&nbsp;نو ځکه مالِک قادر مطلق خُدائ داسې فرمائى چې، افسوس دې وى د وينو تويولو په ښاريې يروشلم باندې. زۀ به هم ورته د اور بلولو دپاره لرګى ډېرے کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19951, 'Ezekiel 24:10', 'Ezekiel', 24, 10, '&nbsp;نو خشاک راجمع کړئ، او اور بل کړئ. غوښه ښه پخه کړئ او مصالحه ورباندې واچوئ او د هډوکو سره يې سکارۀ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19952, 'Ezekiel 24:11', 'Ezekiel', 24, 11, '&nbsp;بيا هغه د تانبې خالى دېګ په سکارو باندې کېږده چې دا ګرم شى او تانبه يې تکه سره شى او ناپاکى په کښې ويلې شى او د هغې زنګ وسوزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19953, 'Ezekiel 24:12', 'Ezekiel', 24, 12, '&nbsp;خو دا ټول کارونه بې‌فائدې وُو، تر دې چې د دې ډېر زيات زنګ په اور هم اخوا نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19954, 'Ezekiel 24:13', 'Ezekiel', 24, 13, '&nbsp;نو اوس تا په خپلو بې‌حيا کارونو خپل ځان پليت کړے دے. ځکه ما کوشش وکړو چې تا د خپلو پليتو عملونو نه پاک کړم، خو تۀ پاک نۀ شوې، تۀ به تر هغې پاک نۀ شې ترڅو چې زۀ خپله مکمله غصه په تا نازله کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19955, 'Ezekiel 24:14', 'Ezekiel', 24, 14, '&nbsp;ما مالِک خُدائ وفرمائيل. زما دپاره هغه وخت رارسېدلے دے چې خپله کاروائى وکړم. زۀ به وروستو نۀ شم، زۀ به رحم نۀ کوم، او نۀ به پښېمانه شم. ستاسو د چال چلن او عملونو په مطابق به ستاسو عدالت وکړم، مالِک خُدائ داسې فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19956, 'Ezekiel 24:15', 'Ezekiel', 24, 15, '&nbsp;د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19957, 'Ezekiel 24:16', 'Ezekiel', 24, 16, '&nbsp;”اے بنى آدمه، په يو ګزار سره به زۀ ستا د سترګو تور، ستا ښځه ختمه کړم. خو تۀ مۀ د غم سندرې وايه مۀ ژړا کوه او مۀ اوښکې تويوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19958, 'Ezekiel 24:17', 'Ezekiel', 24, 17, '&nbsp;چغې سورې مۀ وهه، د مړى دپاره غمرازى مۀ کوه، خپل پټکے په سر وتړه او خپلې څپلۍ دې په پښو کښې واچوه، د خپل مخ لاندې برخه مۀ پټوه او د مړى خېرات مۀ خوره.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19959, 'Ezekiel 24:18', 'Ezekiel', 24, 18, '&nbsp;نو ما په سحر کښې خلقو ته وفرمائيل، او بيا په ماښام کښې زما ښځه مړه شوه. او په بل سحر ما هغه شان وکړل لکه څنګه چې ما ته حکم شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19960, 'Ezekiel 24:19', 'Ezekiel', 24, 19, '&nbsp;نو بيا خلقو زما نه تپوس وکړو چې، ”ولې تۀ به مونږ ته دا ووائې چې ستا د دې کارونو زمونږ دپاره څۀ مطلب دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19961, 'Ezekiel 24:20', 'Ezekiel', 24, 20, '&nbsp;نو ما هغوئ ته ووئيل، ”د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19962, 'Ezekiel 24:21', 'Ezekiel', 24, 21, '&nbsp;د بنى اِسرائيلو قوم ته دا ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى چې زۀ اوس د خپلې مقدسې قربان‌ګاه بې‌حرمتى کوم، هغه مضبوط مقام چې تاسو پرې فخر کوئ ورانوم، ستاسو د سترګو تور يعنې ستاسو ښځې، او ستاسو د زړۀ اُميد تباه کوم. او کوم زامن او لوڼه چې تاسو پرېښودل هغوئ ټول به په تُوره قتل کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19963, 'Ezekiel 24:22', 'Ezekiel', 24, 22, '&nbsp;او تاسو به هغه کار وکړئ کوم چې ما وکړو. تاسو به د خپل مخ لاندې حِصه نۀ پټوئ او نۀ به د مړى خېرات خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19964, 'Ezekiel 24:23', 'Ezekiel', 24, 23, '&nbsp;تاسو به په خپل سر باندې پټکے ساتئ او پېزار به په پښو کوئ. تاسو به غم او ژړا نۀ کوئ، او تاسو به په خپله ګناه کښې ضائع شئ او تاسو به په خپلو ټولو ګناهونو ماتم کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19965, 'Ezekiel 24:24', 'Ezekiel', 24, 24, '&nbsp;ستاسو دپاره حزقى‌ايل يو نمونه دے، تاسو به هم هغه څۀ کوئ څۀ چې هغۀ وکړل. کله چې داسې وشى نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک قادر مطلق خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19966, 'Ezekiel 24:25', 'Ezekiel', 24, 25, '&nbsp;او تۀ اے بنى آدمه، په کومه ورځ چې زۀ د هغوئ مضبوط قلعه، د هغوئ خوشحالى او فخر، د هغوئ د سترګو تور يعنې د هغوئ ښځې، د هغوئ د زړۀ خواهشونه، او د هغوئ زامن او لوڼه ترې نه واخلم', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19967, 'Ezekiel 24:26', 'Ezekiel', 24, 26, '&nbsp;نو په هم هغه ورځ به د يروشليم نه يو بچ شوے سړے تا له راشى او هغه به تا له خبر راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19968, 'Ezekiel 24:27', 'Ezekiel', 24, 27, '&nbsp;نو هم په هغه وخت کښې به ستا خولۀ کولاو شى، او تۀ به د هغۀ سره خبرې وکړې او نور به تۀ خاموشه پاتې نۀ شې. نو تۀ به د هغوئ دپاره نمونه يې، او هغوئ به په دې باندې پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19969, 'Ezekiel 25:1', 'Ezekiel', 25, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19970, 'Ezekiel 25:2', 'Ezekiel', 25, 2, '&nbsp;”اے بنى آدمه خپل مخ دې د عمونيانو په خلاف راوګرځوه او د هغوئ خلاف پېشګوئې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19971, 'Ezekiel 25:3', 'Ezekiel', 25, 3, '&nbsp;عمونيانو ته ووايه چې، د مالِک قادر مطلق خُدائ‎ کلام واورئ. مالِک قادر مطلق خُدائ داسې فرمائى، کله چې زما د عبادتخانې بې‌عزتى کېدله او د بنى اِسرائيلو زمکه شاړه کېدله او د يهوداه خلق جلاوطن کېدل نو تاسو خوشحالى وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19972, 'Ezekiel 25:4', 'Ezekiel', 25, 4, '&nbsp;نو زۀ په دې وجه تاسو د مشرق خلقو ته د ميراث په توګه حواله کوم. هغوئ به ستاسو په مينځ کښې خپل کېمپونه جوړ کړى او خېمې به ودروى، هغوئ به ستاسو مېوې وخورى او ستاسو پئ به وڅښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19973, 'Ezekiel 25:5', 'Ezekiel', 25, 5, '&nbsp;زۀ به د ربه ښار نه د اوښانو د څرن ځائ جوړ کړم او د عمون نه به د ګډو شپول جوړ کړم. نو بيا به تاسو په دې پوهه شئ چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19974, 'Ezekiel 25:6', 'Ezekiel', 25, 6, '&nbsp;نو مالِک قادر مطلق خُدائ داسې فرمائى، ځکه چې تاسو د بنى اِسرائيلو خلاف خپل لاسونه وپړقول او خپلو پښو سره مو زمکه ودربوله، او تاسو د بنى اِسرائيلو د مُلک په تباهۍ خوشحالى وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19975, 'Ezekiel 25:7', 'Ezekiel', 25, 7, '&nbsp;نو په دې وجه به زۀ خپل لاس ستاسو خلاف دروغزوم او تاسو به نورو قومونو ته د غنيمت په توګه حواله کړم. زۀ به ستاسو قوم ختم کړم او تاسو به خانه بدوش کړم او تاسو به تباه کړم. نو تاسو به په دې پوهه شئ چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19976, 'Ezekiel 25:8', 'Ezekiel', 25, 8, '&nbsp;”مالِک قادر مطلق خُدائ داسې فرمائى، نو ځکه چې موآب او سعير وائى وګوره، د يهوداه قوم لکه د نورو ټولو قومونو په شان شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19977, 'Ezekiel 25:9', 'Ezekiel', 25, 9, '&nbsp;نو په دې وجه، زۀ به د موآب سرحدى ښارونه حملې دپاره پرېږدم چې په هغې کښې د بيت‌يسيموت، بعل معون او قِريَتائم ښکلى ښارونه شامل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19978, 'Ezekiel 25:10', 'Ezekiel', 25, 10, '&nbsp;زۀ به د مشرق په خلقو موآب او عمونيان قبضه کړم، نو بيا به نور عمونيان د دُنيا په مُلکونو کښې نۀ ياديږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19979, 'Ezekiel 25:11', 'Ezekiel', 25, 11, '&nbsp;زۀ به په موآبيانو د سزا حکم وکړم. نو بيا به هغوئ په دې پوهه شى چې زۀ مالِک قادر مطلق خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19980, 'Ezekiel 25:12', 'Ezekiel', 25, 12, '&nbsp;”مالِک قادر مطلق خُدائ داسې فرمائى، ځکه چې ادوم د يهوداه د قوم نه په بدله اخستو سره سخت مجرم وګرځولے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19981, 'Ezekiel 25:13', 'Ezekiel', 25, 13, '&nbsp;نو په دې وجه، مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ به خپل لاس د ادوم خلاف وغزوم او د هغۀ خلق او ځناور به ووژنم. زۀ به دا د تيمان نه واخله تر ددان پورې وران ويجاړ کړم او هغوئ به په تُوره قتل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19982, 'Ezekiel 25:14', 'Ezekiel', 25, 14, '&nbsp;زۀ به د خپلو خلقو بنى اِسرائيلو په لاس خپله بدله د ادوميانو نه واخلم، او هغوئ به ورسره زما د قهر و غضب په مطابق رفتار وکړى، هغوئ به زما په بدله اخستو پوهه شى، مالِک قادر مطلق خُدائ داسې فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19983, 'Ezekiel 25:15', 'Ezekiel', 25, 15, '&nbsp;”مالِک قادر مطلق خُدائ داسې فرمائى چې، فلستيانو د يهوداه نه بې‌رحمه بدله واخسته، او هغوئ د خپل زړۀ پخوانۍ کينه او دشمنى ورسره ښکاره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19984, 'Ezekiel 25:16', 'Ezekiel', 25, 16, '&nbsp;نو په دې وجه، مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ به د فلستيانو خلاف خپل لاس ورغزوم، او زۀ به چريتيان ختم کړم او څوک چې د سمندر په غاړه اوسيږى هغوئ به تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19985, 'Ezekiel 25:17', 'Ezekiel', 25, 17, '&nbsp;او زۀ به د هغوئ نه سخته بدله واخلم او په خپل غضب کښې به ورله سزا ورکړم. نو بيا به هغوئ په دې پوهه شى چې زۀ مالِک قادر مطلق خُدائ يم، کله چې زۀ د هغوئ نه بدله واخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19986, 'Ezekiel 26:1', 'Ezekiel', 26, 1, '&nbsp;د جلاوطنۍ په يوولسم کال، د مياشتې په وړومبۍ ورځ کښې د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19987, 'Ezekiel 26:2', 'Ezekiel', 26, 2, '&nbsp;”اے بنى آدمه، ځکه چې صور د يروشلم په حقله داسې وئيلى دى چې، آو، د دې قومونو دروازه ماته شوې ده، او د هغوئ دروازې بلکل زما دپاره کولاو دى، نو اوس هغه تباه پرته ده نو زۀ به آباده شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19988, 'Ezekiel 26:3', 'Ezekiel', 26, 3, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ فرمائى چې، اے صوره زۀ ستا خلاف يم، زۀ به ستا خلاف ډېر قومونه راوچت کړم لکه څنګه چې سمندر خپلې چپې راوچتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19989, 'Ezekiel 26:4', 'Ezekiel', 26, 4, '&nbsp;هغوئ به د صور دېوالونه تباه کړى او د هغۀ برجونه به راګزار کړى او زۀ به د هغوئ ملبه داسې جارُو کړم چې لکه د صفا ګټ په شان پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19990, 'Ezekiel 26:5', 'Ezekiel', 26, 5, '&nbsp;دا به لکه په سمندر کښې د ماهيګرو د جال د خورولو ځائ په شان وى، ځکه چې ما مالِک قادر مطلق خُدائ دا وفرمائيل چې، نور قومونه به هغه په آسانۍ سره لوټ کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19991, 'Ezekiel 26:6', 'Ezekiel', 26, 6, '&nbsp;او په هغه اصلى زمکه باندې به د هغې اوسېدونکى په تُورو قتل شى. نو بيا به هغوئ په دې پوهه شى چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19992, 'Ezekiel 26:7', 'Ezekiel', 26, 7, '&nbsp;نو ځکه مالِک قادر مطلق خُدائ داسې فرمائى، زۀ به د شمال د خوا نه د بابل بادشاه نبوکدنضر د بادشاهانو بادشاه، د آسونو او جنګى ګاډو، د سوارو او د لوئ لښکر سره د هغوئ خلاف راولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19993, 'Ezekiel 26:8', 'Ezekiel', 26, 8, '&nbsp;او په هغه اصلى زمکه به د هغې اوسېدونکى په تُورو قتل شى، هغه به ستا خلاف د خاورو ډېرے جوړ کړى، او ستاسو دېوالونو ته به لارې جوړې کړى او خپل ډالونه به ستا خلاف راوچت کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19994, 'Ezekiel 26:9', 'Ezekiel', 26, 9, '&nbsp;هغه به ستا دېوالونه په مشين سره راګزار کړى او په خپلې وسلې سره به ستا برجونه راونړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19995, 'Ezekiel 26:10', 'Ezekiel', 26, 10, '&nbsp;د هغوئ آسونه به دومره زيات وى چې په خپلو دوړو کښې به تا پټ کړى. او د جنګى آسونو د شور نه به ستا دېوالونه په لړزان شى، د هغې بګۍ او جنګى ګاډۍ چې کله ستا د ښار دروازې ته درننوځى دا به د هغه ښار په شان وى د چا دېوالونه چې د مخکښې نه وران شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19996, 'Ezekiel 26:11', 'Ezekiel', 26, 11, '&nbsp;ستا لارې کوڅې به د خپلو آسونو د پښو د نوکو لاندې کړى، او هغه به ستا خلق په تُوره قتل کړى، او ستا مضبوطې ستنې به په زمکه لاندې راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19997, 'Ezekiel 26:12', 'Ezekiel', 26, 12, '&nbsp;هغوئ به ستا مال دولت لوټ کړى او ستا د تجارت سامان به لوټ کړى، هغوئ به ستا دېوالونه مات کړى او ستا ښکلې کورونه به راوغورزوى او ستا کاڼى، لرګى او ملبه به په سمندر کښې وغورزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19998, 'Ezekiel 26:13', 'Ezekiel', 26, 13, '&nbsp;زۀ به ستا د سندرو آواز ختم کړم او ستا د رباب آواز به نور نۀ اورېدلے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19999, 'Ezekiel 26:14', 'Ezekiel', 26, 14, '&nbsp;زۀ به تا بربنډ ګټ کړم، او تۀ به هغه ځائ وګرځې چرته چې خلق د ماهيانو جال خوروى. تۀ به بيا آباد نۀ شې ځکه چې مالِک خُدائ فرمائيلى دى، مالِک قادر مطلق خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20000, 'Ezekiel 26:15', 'Ezekiel', 26, 15, '&nbsp;دا هغه څۀ دى چې مالِک قادر مطلق خُدائ يې صور ته فرمائى، آيا د سمندر ساحلى ځايونه به ستا د راغورزېدو د آواز په وجه د يرې نه ونۀ لړزيږى کله چې زخميان چغې سورې وهى او په تا کښې خلق حلاليږى؟ ‎', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');